# Check if simple periodic row stripes fit all demo anchors, and list candidates.
anchors=[(4,3),(6,7),(17,9),(23,1),(1,2),(2,1),(4,8),(6,9),(10,4),(12,5),(0,8),(4,6),(7,1),(18,4),(0,5)]
for p in range(1,14):
 d={}
 ok=True
 for r,c in anchors:
  if r%p in d and d[r%p]!=c: ok=False; break
  d[r%p]=c
 if ok: print(p,d)
